-- 外研社七上(wy7A) 词表灌库 · Aaron service role 跑 · 幂等(先 DELETE by publisher+volume 再 INSERT,可重跑)
-- publisher=junior_fltrp / volume=wy7A / grade=7 / unit∈{Starter,U1..U6}; 短语 pos/phonetic=NULL; freq_rank=课本顺序
-- ★DELETE 带 publisher='junior_fltrp' AND volume='wy7A',绝不动人教行★
BEGIN;
DELETE FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7A';
-- 校验:应 288 行
SELECT unit, count(*) FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7A' GROUP BY unit ORDER BY min(freq_rank);
COMMIT;